# --- quotas ---------------------------------------------------------

def declare_quota(self, raw: Any, key: str | None, tenant: str) -> dict[str, Any]:
    if not tenant:
        raise ValidationError("tenant id must be a non-empty string")
    if not isinstance(raw, dict) or set(raw) != {"workflows", "executions"}:
